}

impl Default for ContextOptions<'_> {
    fn default() -> Self {
        Self {
            limit: 8,
            snippets_per_file: 2,
            include_snippets: true,
            why_debug: false,
            hybrid: HybridOptions::default(),
            error_frames: &[],
            git_boost: false,
            memory_boost: false,
        }
    }
}

impl Default for HybridOptions<'_> {
    fn default() -> Self {
        Self {
            embeddings: false,
            #[cfg(feature = "embed")]
            embedder: None,
            _marker: std::marker::PhantomData,
        }
    }
}

impl<'a> HybridOptions<'a> {
    pub fn embeddings(embeddings: bool) -> Self {
        Self {
            embeddings,
            #[cfg(feature = "embed")]
            embedder: None,
            _marker: std::marker::PhantomData,
        }
    }

    #[cfg(feature = "embed")]
    pub fn with_embedder(embeddings: bool, embedder: &'a dyn embed::LocalEmbedder) -> Self {
        Self {
            embeddings,
            embedder: Some(embedder),
            _marker: std::marker::PhantomData,
        }
    }
}

