    if !root.is_empty() {
        output.push_str(&format!("Root: {root}\n"));
    }
    output.push_str(&format!("Grep policy: {grep_policy}\n\n"));
    if let Some(tokens) = json_usize(context, &["retrieval_cost", "retrieval_model_tokens"]) {
        output.push_str(&format!(
