fn resolve_import(
    root: &Path,
    source: &Path,
    language: Language,
    imported: &str,
) -> Option<String> {
    match language {
        Language::TypeScript | Language::JavaScript => {
            if !imported.starts_with('.') {
                return None;
            }
            let base = source.parent().unwrap_or_else(|| Path::new(""));
            let candidate = normalize_relative(base.join(imported));
            let extensions: &[&str] = if language == Language::TypeScript {
                &["ts", "tsx", "js", "jsx"]
            } else {
                &["js", "jsx", "ts", "tsx"]
            };
            resolve_candidate(root, &candidate, extensions).map(|path| path_to_string(&path))
        }
        Language::Python => resolve_python_import(root, source, imported),
        Language::Rust => resolve_rust_import(root, source, imported),
        Language::Php => resolve_relative_import(root, source, imported, &["php", "phtml"]),
        Language::Ruby => resolve_relative_import(root, source, imported, &["rb"]),
        Language::Dart => resolve_relative_import(root, source, imported, &["dart"]),
        Language::Shell => resolve_relative_import(root, source, imported, &["sh", "bash", "zsh"]),
        Language::C => resolve_relative_import(root, source, imported, &["h", "c"]),
        Language::Cpp => resolve_relative_import(
            root,
            source,
            imported,
            &["hpp", "hh", "hxx", "h", "cpp", "cc", "cxx"],
        ),
        Language::Go
        | Language::Java
        | Language::CSharp
        | Language::Kotlin
        | Language::Swift
        | Language::Scala
        | Language::Lua => None,
        Language::Markdown | Language::Json | Language::Toml | Language::Yaml | Language::Text => {
            None
        }
    }
}

fn resolve_relative_import(
    root: &Path,
    source: &Path,
    imported: &str,
    extensions: &[&str],
) -> Option<String> {
    let imported = imported
        .trim()
        .trim_end_matches(';')
        .trim_matches(['"', '\'', '<', '>']);
    if imported.is_empty() || !(imported.starts_with('.') || imported.contains('/')) {
        return None;
    }
    let base = source.parent().unwrap_or_else(|| Path::new(""));
    let candidate = normalize_relative(base.join(imported));
    resolve_candidate(root, &candidate, extensions).map(|path| path_to_string(&path))
}

fn resolve_candidate(root: &Path, candidate: &Path, extensions: &[&str]) -> Option<PathBuf> {
    if root.join(candidate).is_file() {
        return Some(candidate.to_path_buf());
    }

    for extension in extensions {
        let with_extension = candidate.with_extension(extension);
        if root.join(&with_extension).is_file() {
            return Some(with_extension);
        }
    }

    for extension in extensions {
        let index_file = candidate.join(format!("index.{extension}"));
        if root.join(&index_file).is_file() {
            return Some(index_file);
        }
    }

    if extensions.contains(&"py") {
        let init_file = candidate.join("__init__.py");
        if root.join(&init_file).is_file() {
            return Some(init_file);
        }
    }

    None
}

fn normalize_relative(path: PathBuf) -> PathBuf {
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                normalized.pop();
            }
            other => normalized.push(other.as_os_str()),
        }
    }
    normalized
}

fn resolve_python_import(root: &Path, source: &Path, imported: &str) -> Option<String> {
    let raw_imported = imported.trim();
    let imported = raw_imported.trim_start_matches('.');
    if imported.is_empty() {
        return None;
    }

    let module_path = PathBuf::from(imported.replace('.', "/"));
    let mut candidates = vec![module_path.clone(), PathBuf::from("src").join(&module_path)];

    if let Some(top_level) = source.components().next() {
        candidates.push(PathBuf::from(top_level.as_os_str()).join(&module_path));
    }

    if raw_imported.starts_with('.') {
        let base = source.parent().unwrap_or_else(|| Path::new(""));
        candidates.push(normalize_relative(base.join(&module_path)));
    }

    candidates.into_iter().find_map(|candidate| {
        resolve_candidate(root, &candidate, &["py"]).map(|path| path_to_string(&path))
    })
}

fn resolve_rust_import(root: &Path, source: &Path, imported: &str) -> Option<String> {
    let imported = imported
        .trim()
        .trim_end_matches(';')
        .split_once(" as ")
        .map(|(path, _)| path)
        .unwrap_or(imported)
        .trim();
    let imported = imported
        .split_once('{')
        .map(|(prefix, _)| prefix.trim_end_matches("::"))
        .unwrap_or(imported);
    let parts: Vec<&str> = imported
        .split("::")
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .collect();
    if parts.is_empty() {
        return None;
    }

    let base = rust_import_base(source, parts[0]);
    let mut module_parts = match parts[0] {
        "crate" | "self" | "super" => parts[1..].to_vec(),
        _ => parts.clone(),
    };
    if module_parts.is_empty() {
        return None;
    }

    let mut candidates = Vec::new();
    candidates.push(base.join(module_parts.join("/")));
    module_parts.pop();
    if !module_parts.is_empty() {
        candidates.push(base.join(module_parts.join("/")));
    }

    candidates.into_iter().find_map(|candidate| {
        resolve_candidate(root, &candidate, &["rs"]).map(|path| path_to_string(&path))
    })
}

fn rust_import_base(source: &Path, prefix: &str) -> PathBuf {
    match prefix {
        "self" => source
            .parent()
            .unwrap_or_else(|| Path::new(""))
            .to_path_buf(),
        "super" => source
            .parent()
            .and_then(Path::parent)
            .unwrap_or_else(|| Path::new(""))
            .to_path_buf(),
        _ => {
            let mut base = PathBuf::new();
            for component in source.components() {
                base.push(component.as_os_str());
                if component.as_os_str().to_string_lossy() == "src" {
                    return base;
                }
            }
            source
                .parent()
                .unwrap_or_else(|| Path::new(""))
                .to_path_buf()
        }
    }
}

fn build_references(
    file_contents: &[(String, String, Language, String)],
    files: &[FileRecord],
    symbols: &[SymbolRecord],
    imports: &[ImportRecord],
) -> Vec<ReferenceRecord> {
    let candidate_names: std::collections::BTreeSet<String> = symbols
        .iter()
        .map(|symbol| symbol.name.clone())
        .chain(
            imports
                .iter()
                .flat_map(|import| import.aliases.iter().map(|alias| alias.local.clone())),
        )
        .collect();
    let mut references = Vec::new();
    let resolver = ReferenceResolver::new(files, symbols, imports);

    for (file_id, path, language, content) in file_contents {
        for raw in references::extract_references(content, *language, &candidate_names) {
            let target = resolver.resolve_reference_target(file_id, path, &raw.target_name);
            references.push(ReferenceRecord {
                file_id: file_id.clone(),
                source_path: path.clone(),
                source_symbol_id: resolver
                    .source_symbol_for_line(file_id, raw.line)
                    .map(|symbol| symbol.id.clone()),
                target_name: raw.target_name,
                target_symbol_id: target.map(|symbol| symbol.id.clone()),
                target_path: target
                    .and_then(|symbol| resolver.file_for_id(&symbol.file_id))
                    .map(|file| file.path.clone()),
                kind: raw.kind,
                line: raw.line,
                edge_source: raw.edge_source,
                confidence: raw.confidence,
                lsp_method: None,
                // a range equal to `line` is implied; omitted to keep the index small
                source_range: None,
                target_range: target.map(|symbol| [symbol.start_line, symbol.end_line]),
            });
        }
    }

    references
}

struct ReferenceResolver<'a> {
    files_by_id: BTreeMap<&'a str, &'a FileRecord>,
    symbols_by_file: BTreeMap<&'a str, Vec<&'a SymbolRecord>>,
    symbols_by_file_and_name: BTreeMap<(&'a str, &'a str), Vec<&'a SymbolRecord>>,
    symbols_by_name: BTreeMap<&'a str, Vec<&'a SymbolRecord>>,
    imports_by_source_path: BTreeMap<&'a str, Vec<&'a ImportRecord>>,
}

impl<'a> ReferenceResolver<'a> {
    fn new(
        files: &'a [FileRecord],
        symbols: &'a [SymbolRecord],
        imports: &'a [ImportRecord],
    ) -> Self {
        let mut files_by_id = BTreeMap::new();
        for file in files {
            files_by_id.insert(file.id.as_str(), file);
        }

        let mut symbols_by_file: BTreeMap<&str, Vec<&SymbolRecord>> = BTreeMap::new();
        let mut symbols_by_file_and_name: BTreeMap<(&str, &str), Vec<&SymbolRecord>> =
            BTreeMap::new();
        let mut symbols_by_name: BTreeMap<&str, Vec<&SymbolRecord>> = BTreeMap::new();
        for symbol in symbols {
            symbols_by_file
                .entry(symbol.file_id.as_str())
                .or_default()
                .push(symbol);
            symbols_by_file_and_name
                .entry((symbol.file_id.as_str(), symbol.name.as_str()))
                .or_default()
                .push(symbol);
            symbols_by_name
                .entry(symbol.name.as_str())
                .or_default()
                .push(symbol);
        }

        let mut imports_by_source_path: BTreeMap<&str, Vec<&ImportRecord>> = BTreeMap::new();
        for import in imports {
            imports_by_source_path
                .entry(import.source_path.as_str())
                .or_default()
                .push(import);
        }

        Self {
            files_by_id,
            symbols_by_file,
            symbols_by_file_and_name,
            symbols_by_name,
            imports_by_source_path,
        }
    }

    fn file_for_id(&self, file_id: &str) -> Option<&'a FileRecord> {
        self.files_by_id.get(file_id).copied()
    }

    fn source_symbol_for_line(&self, file_id: &str, line: usize) -> Option<&'a SymbolRecord> {
        self.symbols_by_file
            .get(file_id)
            .into_iter()
            .flatten()
            .filter(|symbol| symbol.start_line <= line && symbol.end_line >= line)
            .min_by_key(|symbol| symbol.end_line.saturating_sub(symbol.start_line))
            .copied()
    }

    fn resolve_reference_target(
        &self,
        file_id: &str,
        source_path: &str,
        target_name: &str,
    ) -> Option<&'a SymbolRecord> {
        let same_file = self
            .symbols_by_file_and_name
            .get(&(file_id, target_name))
            .map(Vec::as_slice)
            .unwrap_or(&[]);
        if same_file.len() == 1 {
            return same_file.first().copied();
        }

        if let Some(source_imports) = self.imports_by_source_path.get(source_path) {
            for import in source_imports {
                for alias in &import.aliases {
                    if alias.local == target_name
                        && let Some(imported_path) = import.resolved_path.as_deref()
                    {
                        let imported_name = import_alias_target_name(&alias.imported, target_name);
                        let imported_symbols: Vec<&SymbolRecord> = self
                            .symbols_by_name
                            .get(imported_name)
                            .into_iter()
                            .flatten()
                            .filter(|symbol| {
                                self.file_for_id(&symbol.file_id)
                                    .is_some_and(|file| file.path == imported_path)
                            })
                            .copied()
                            .collect();
                        if imported_symbols.len() == 1 {
                            return imported_symbols.first().copied();
                        }
                    }
                }
            }
        }

        let imported_paths: std::collections::BTreeSet<&str> = self
            .imports_by_source_path
            .get(source_path)
            .into_iter()
            .flatten()
            .filter_map(|import| import.resolved_path.as_deref())
            .collect();
        let imported_symbols: Vec<&SymbolRecord> = self
            .symbols_by_name
            .get(target_name)
            .into_iter()
            .flatten()
            .filter(|symbol| {
                self.file_for_id(&symbol.file_id)
                    .is_some_and(|file| imported_paths.contains(file.path.as_str()))
            })
            .copied()
            .collect();
        if imported_symbols.len() == 1 {
            return imported_symbols.first().copied();
        }

        let global_symbols = self
            .symbols_by_name
            .get(target_name)
            .map(Vec::as_slice)
            .unwrap_or(&[]);
        (global_symbols.len() == 1).then(|| global_symbols[0])
    }
}

fn import_alias_target_name<'a>(imported: &'a str, fallback: &'a str) -> &'a str {
    if imported == "*" {
        return fallback;
    }
    imported
        .rsplit("::")
        .next()
        .unwrap_or(imported)
        .rsplit('.')
        .next()
        .unwrap_or(imported)

