pub mod tree_sitter_symbols;
pub mod walker;

use std::{
    collections::BTreeMap,
    fs,
    path::{Path, PathBuf},
    time::{SystemTime, UNIX_EPOCH},
};

use anyhow::{Context, Result};

use crate::store::{
    CodeIndex, FileRecord, ImportAliasRecord, ImportRecord, IndexMetadata, ReferenceRecord,
    SymbolRecord,
};

use self::language::Language;

pub const SCHEMA_VERSION: u32 = 9;

#[derive(Debug, Clone)]
pub struct IndexOptions {
    pub lsp: bool,
    pub watch_status: String,
    pub watcher_mode: String,
    pub index_generation: u64,
    pub last_error: Option<String>,
}

impl Default for IndexOptions {
    fn default() -> Self {
        Self {
            lsp: false,
            watch_status: "unwatched".to_string(),
            watcher_mode: "none".to_string(),
            index_generation: 0,
            last_error: None,
        }
    }
}

pub fn build_index(root: &Path) -> Result<CodeIndex> {
    build_index_with_options(root, IndexOptions::default())
}

pub fn build_index_with_options(root: &Path, options: IndexOptions) -> Result<CodeIndex> {
    let root = root
        .canonicalize()
        .with_context(|| format!("failed to resolve repo root {}", root.display()))?;
    let mut warnings = Vec::new();
    let mut files = Vec::new();
    let mut symbols = Vec::new();
    let mut imports = Vec::new();
    let mut file_contents = Vec::new();
    let ownership_resolver = self::ownership::OwnershipResolver::from_repo_root(&root)
        .filter(|resolver| !resolver.is_empty());
    let git_signals = self::git::collect_git_signals(&root);

    for relative_path in walker::source_files(&root)? {
        let absolute_path = root.join(&relative_path);
        let path_string = path_to_string(&relative_path);
        let language = Language::from_path(&relative_path).expect("walker only returns languages");
        let bytes = match fs::read(&absolute_path) {
            Ok(bytes) => bytes,
            Err(error) => {
                warnings.push(format!("skipped unreadable file {path_string}: {error}"));
                continue;
            }
        };
        let content = match String::from_utf8(bytes.clone()) {
            Ok(content) => content,
            Err(_) => {
                warnings.push(format!("skipped non-UTF8 file {path_string}"));
                continue;
            }
        };
        let metadata = fs::metadata(&absolute_path)
            .with_context(|| format!("failed to stat {}", absolute_path.display()))?;
        let file_id = file_id(&path_string);
        let ownership = ownership_resolver.as_ref().and_then(|resolver| {
            let computed = resolver.ownership_for(&path_string);
            if computed.is_empty() {
                None
            } else {
                Some(computed)
            }
        });
        let file = FileRecord {
            id: file_id.clone(),
            path: path_string.clone(),
            language,
            size_bytes: metadata.len(),
            line_count: content.lines().count(),
            mtime: metadata_mtime(&metadata),
            content_hash: stable_content_hash(&bytes),
            is_test: is_test_file(&path_string),
            is_config: is_config_file(&path_string),
            module_path: module_path(&relative_path),
            content_terms: content_terms(&content, language),
            ownership,
            git: git_signals.get(&path_string).cloned(),
        };

        if language.is_code() {
            for symbol in symbols::extract_symbols(&content, language) {
                symbols.push(SymbolRecord {
                    id: symbol_id(&path_string, symbol.start_line, &symbol.name),
                    file_id: file_id.clone(),
                    name: symbol.name,
                    kind: symbol.kind,
                    language,
                    start_line: symbol.start_line,
                    end_line: symbol.end_line,
                    visibility: symbol.visibility,
                    parent: symbol.parent,
                    signature: symbol.signature,
                    doc: symbol.doc,
                });
            }

            for import in imports::extract_imports(&content, language) {
                imports.push(ImportRecord {
                    file_id: file_id.clone(),
                    source_path: path_string.clone(),
                    resolved_path: resolve_import(
                        &root,
                        &relative_path,
                        language,
                        &import.imported,
                    ),
                    imported: import.imported,
                    aliases: import
                        .aliases
                        .into_iter()
                        .map(|alias| ImportAliasRecord {
                            local: alias.local,
                            imported: alias.imported,
                        })
                        .collect(),
                });
            }
        }

        files.push(file);
        file_contents.push((file_id, path_string, language, content));
    }

    files.sort_by(|left, right| left.path.cmp(&right.path));
    symbols.sort_by(|left, right| {
        left.file_id
            .cmp(&right.file_id)
            .then(left.start_line.cmp(&right.start_line))
            .then(left.name.cmp(&right.name))
    });
    imports.sort_by(|left, right| {
        left.source_path
            .cmp(&right.source_path)
            .then(left.imported.cmp(&right.imported))
    });
    let mut references = build_references(&file_contents, &files, &symbols, &imports);
    let mut lsp_enriched = false;
    if options.lsp {
        let lsp_references = lsp::enrich_references(&root, &file_contents, &files, &symbols);
        lsp_enriched = !lsp_references.is_empty();
        references = merge_references(references, lsp_references);
    }
    references.sort_by(|left, right| {
        left.source_path
            .cmp(&right.source_path)
            .then(left.line.cmp(&right.line))
            .then(left.target_name.cmp(&right.target_name))
            .then(left.kind.cmp(&right.kind))
    });

    let lsp_servers = lsp::server_statuses(&files);
    let indexed_at = now_unix_seconds();

    Ok(CodeIndex {
        schema_version: SCHEMA_VERSION,
        root: ".".to_string(),
        files,
        symbols,
        imports,
        references,
        metadata: IndexMetadata {
            indexed_at,
            watch_status: options.watch_status,
            watcher_mode: options.watcher_mode,
            index_generation: options.index_generation,
            lsp_enriched,
            lsp_enriched_at: if lsp_enriched { indexed_at } else { 0 },
            last_error: options.last_error,
            lsp_servers,
        },
        warnings,
    })
}

pub fn path_to_string(path: &Path) -> String {
    path.to_string_lossy().replace('\\', "/")
}

fn file_id(path: &str) -> String {
    format!("file:{path}")
}

fn symbol_id(path: &str, line: usize, name: &str) -> String {
    format!("symbol:{path}:{line}:{name}")
}

pub(crate) fn metadata_mtime(metadata: &fs::Metadata) -> u64 {
    metadata
        .modified()
        .ok()
        .and_then(|time| time.duration_since(UNIX_EPOCH).ok())
        .map(|duration| duration.as_secs())
        .unwrap_or_default()
}

fn now_unix_seconds() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or_default()
}

/// Fingerprint of the indexed file set and contents: stable across machines
/// and build times because it hashes only file ids and content hashes.
pub fn index_fingerprint(index: &crate::store::CodeIndex) -> String {
    let mut bytes = Vec::new();
    for file in &index.files {
        bytes.extend_from_slice(file.id.as_bytes());
        bytes.push(0);
        bytes.extend_from_slice(file.content_hash.as_bytes());
        bytes.push(b'\n');
    }
    stable_content_hash(&bytes)
}

pub(crate) fn stable_content_hash(bytes: &[u8]) -> String {
    let mut hash = 0xcbf29ce484222325_u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("fnv1a64:{hash:016x}")
}

fn module_path(path: &Path) -> String {
    path.parent().map(path_to_string).unwrap_or_default()
}

pub(crate) fn is_test_file(path: &str) -> bool {
    let lower = path.replace('\\', "/").to_ascii_lowercase();
    // Match both nested (`src/tests/`, `src/test/`) and top-level (`tests/`,
    // `test/`) test dirs; paths are repo-relative with no leading slash, so a
    // `/tests/` check alone misses the common top-level `tests/` and
    // `__tests__/` convention.
    lower.contains("/__tests__/")
        || lower.starts_with("__tests__/")
        || lower.contains("/test/")
        || lower.starts_with("test/")
        || lower.contains("/tests/")
        || lower.starts_with("tests/")
        || lower.contains("_test.")
        || lower.contains(".test.")
        || lower.contains(".spec.")
        || lower.ends_with("_test.rs")
}

fn is_config_file(path: &str) -> bool {
    let lower = path.to_ascii_lowercase();
    let file = lower.rsplit('/').next().unwrap_or(lower.as_str());
    lower.starts_with(".github/workflows/")
        || file.contains("config")
        || matches!(
            file,
            "build.rs"
                | "cargo.toml"
                | "package.json"
                | "pyproject.toml"
                | "requirements.txt"
                | "rust-toolchain.toml"
                | "rustfmt.toml"
                | "clippy.toml"
        )
}

fn content_terms(content: &str, language: Language) -> Vec<String> {
    let code_content;
    let content = if language.is_code() {
        code_content = strip_comment_only_lines(content);
        code_content.as_str()
    } else {
        content
    };
    let mut counts = BTreeMap::new();
    for token in tokenize_content(content) {
        *counts.entry(token).or_insert(0usize) += 1;
    }

    let mut ranked_terms: Vec<(String, usize)> = counts.into_iter().collect();
    ranked_terms.sort_by(|left, right| right.1.cmp(&left.1).then(left.0.cmp(&right.0)));
    ranked_terms
        .into_iter()
        .take(if language.is_code() { 80 } else { 120 })
        .map(|(term, _)| term)
        .collect()
}

fn strip_comment_only_lines(content: &str) -> String {
    content
        .lines()
        .filter(|line| {
            let trimmed = line.trim_start();
            !(trimmed.starts_with("//")
                || trimmed.starts_with('#')
                || trimmed.starts_with("/*")
                || trimmed.starts_with('*'))
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn tokenize_content(input: &str) -> Vec<String> {
    const STOP_WORDS: &[&str] = &[
        "a", "an", "and", "are", "as", "at", "be", "by", "for", "from", "how", "in", "is", "it",
        "of", "on", "or", "that", "the", "this", "to", "with",
    ];

    split_camel_case(input)
        .split(|character: char| !character.is_ascii_alphanumeric())
        .map(|token| token.trim().to_ascii_lowercase())
        .filter(|token| token.len() > 1)
        .filter(|token| !STOP_WORDS.contains(&token.as_str()))
        .collect()
}

fn split_camel_case(input: &str) -> String {
    let mut output = String::with_capacity(input.len() + 8);
    let mut previous_lowercase = false;

    for character in input.chars() {
        if previous_lowercase && character.is_ascii_uppercase() {
            output.push(' ');
        }
        previous_lowercase = character.is_ascii_lowercase() || character.is_ascii_digit();
        output.push(character);
    }

    output
}

    })
}

fn blast_radius_for(
    imports: &[String],
    referenced_by: &[String],
    related_tests: &[RelatedTest],
    calls: &[ReferenceEdge],
    called_by: &[ReferenceEdge],
) -> BlastRadius {
    let tests: Vec<String> = related_tests.iter().map(|test| test.file.clone()).collect();
    let call_targets = edge_files(calls, true);
    let callers = edge_files(called_by, false);
    let total_edges = imports.len() + referenced_by.len() + call_targets.len() + callers.len();
    let risk = if referenced_by.len() >= 5 || callers.len() >= 5 || total_edges >= 8 {
        "high"
    } else if total_edges > 0 || !tests.is_empty() {
        "medium"
    } else {
        "low"
    };

    BlastRadius {
        imports: take_string_refs(imports, MAX_CONTEXT_RELATION_FILES),
        referenced_by: take_string_refs(referenced_by, MAX_CONTEXT_RELATION_FILES),
        tests: take_strings(tests, MAX_CONTEXT_RELATED_TESTS),
        calls: take_strings(call_targets, MAX_CONTEXT_RELATION_FILES),
        called_by: take_strings(callers, MAX_CONTEXT_RELATION_FILES),
        risk: risk.to_string(),
    }
}

fn edge_files(edges: &[ReferenceEdge], use_target: bool) -> Vec<String> {
    let mut files: Vec<String> = edges
        .iter()
        .filter_map(|edge| {
            if use_target {
                edge.target_file.clone()
            } else {
                Some(edge.file.clone())
            }
        })
        .collect();
    files.sort();
    files.dedup();
    files
}

fn take_strings(values: Vec<String>, limit: usize) -> Vec<String> {
    values.into_iter().take(limit).collect()
}

fn take_string_refs(values: &[String], limit: usize) -> Vec<String> {
    values.iter().take(limit).cloned().collect()
}

fn compact_related_tests(tests: Vec<RelatedTest>) -> Vec<RelatedTest> {
    tests
        .into_iter()
        .take(MAX_CONTEXT_RELATED_TESTS)
        .map(|test| RelatedTest {
            file: test.file,
            symbols: test
                .symbols
                .into_iter()
                .take(MAX_CONTEXT_RELATED_TEST_SYMBOLS)
                .collect(),
        })
        .collect()
}

struct BaselineReplay {
    benchmark: BaselineBenchmark,
    matched_files: Vec<String>,
}

    let output = build_context(
